#!/usr/bin/env bash
# Zellige — all-in-one. نفس استعمال zellige.sh:
#   bash zellige-all-in-one.sh /path/to/AndroidIDE [all|inject|rebrand|undo|status] [--name NAME]
set -euo pipefail
command -v base64 >/dev/null 2>&1 || { echo "❌ خاصك base64"; exit 1; }
TMP="$(mktemp -d "${TMPDIR:-/tmp}/zellige.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
sed '1,/^__ZELLIGE_PAYLOAD__$/d' "$0" | base64 -d | tar xz -C "$TMP"
bash "$TMP/zellige-kit/zellige.sh" "$@"
exit $?
__ZELLIGE_PAYLOAD__

